 "content": "def transform(grid):
    # Count separate colored horizontal bars, then pack their colors into a 2x3 tile.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    counts = {}
    for r, row in enumerate(grid):
        seen = set()
        for c, v in enumerate(row):
            if v != bg and v not in seen:
                seen.add(v)
                counts[v] = counts.get(v, 0) + 1
    # Use the two non-background colors in numeric order; each occurrence is one bar.
    colors = sorted(counts)
    vals = []
    for color in colors:
        vals.extend([color] * counts[color])
    vals = (vals + [0] * 6)[:6]
    return [vals[:3], vals[3:]]

if __name__ == '__main__':
    # sanity checks on the demonstrated component counts
    assert transform([[8,3,3,8],[8,2,2,8]]) == [[2,2,0],[0,0,0]]
